    "content": "// Light / dark / system switcher (shadcn's ModeToggle pattern). useTheme() is the host's\n// next-themes-style API: the mode applies to the whole portal (host element + overlays).\nimport { useTheme } from '@portal/runtime'\nimport { Button } from 'components:button'\nimport { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem } from 'components:dropdown-menu'\n\nconst Sun = () => (\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" className=\"size-4 scale-100 rotate-0 transition-all dark:scale-0 dark:-rotate-90\">\n        <circle cx=\"12\" cy=\"12\" r=\"4\" />\n        <path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\" />\n    </svg>\n)\n\nconst Moon = () => (\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" className=\"absolute size-4 scale-0 rotate-90 transition-all dark:scale-100 dark:rotate-0\">\n        <path d=\"M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z\" />\n    </svg>\n)\n\nconst MODES = [\n    { value: 'light', label: 'Light' },\n    { value: 'dark', label: 'Dark' },\n    { value: 'system', label: 'System' },\n] as const\n\nexport function ModeToggle() {\n    const { theme, setTheme } = useTheme()\n    return (\n        <DropdownMenu>\n            <DropdownMenuTrigger render={<Button variant=\"ghost\" size=\"icon-sm\" aria-label=\"Toggle theme\" className=\"relative\" />}>\n                <Sun />\n                <Moon />\n            </DropdownMenuTrigger>\n            <DropdownMenuContent align=\"end\">\n                {MODES.map((m) => (\n                    <DropdownMenuItem key={m.value} onClick={() => setTheme(m.value)}>\n                        {m.label}\n                        {theme === m.value ? <span className=\"ml-auto text-xs text-muted-foreground\">✓</span> : null}\n                    </DropdownMenuItem>\n                ))}\n            </DropdownMenuContent>\n        </DropdownMenu>\n    )\n}\n"
