  "clientScript": "import { Region } from '@portal/runtime'\n\ntype Options = { texture?: 'noise' | 'plain'; contentPadding?: 'none' | 'sm' | 'md' | 'lg' }\n\n/**\n * Dashboard shell (shadcn sidebar variant=\"inset\"): the sidebar and the top header sit directly on\n * the textured page background; main is an inset card with an optional sub-header bar and a\n * scrolling body capped at the page's content width.\n *\n *   ┌ sidebar ┐┌ header ───────────────────────────┐\n *   │         │╭ card ─────────────────────────────╮\n *   │         ││ subheader                         │\n *   │         ││ main (scrolls)                    │\n *   │         │╰───────────────────────────────────╯\n *   └─────────┘  footer\n *\n * Structure only: the widgets own their look. Options switch CSS, never the element tree.\n */\nexport default function AppShell({ options = {} }: { options?: Options }) {\n    const pad = ['none', 'sm', 'md', 'lg'].includes(options.contentPadding as string) ? options.contentPadding : 'md'\n    return (\n        <div className=\"rp-app\" data-texture={options.texture === 'plain' ? 'plain' : 'noise'} data-pad={pad}>\n            <Region name=\"sidebar\" as=\"aside\" className=\"rp-app__sidebar rp-app__slot\" />\n            <div className=\"rp-app__column\">\n                <Region name=\"header\" as=\"header\" className=\"rp-app__header rp-app__slot\" />\n                <div className=\"rp-app__row\">\n                    <main className=\"rp-app__card\">\n                        <Region name=\"subheader\" className=\"rp-app__subheader rp-app__slot\" />\n                        <div className=\"rp-app__scroll\">\n                            <Region name=\"main\" className=\"rp-app__content\" />\n                        </div>\n                    </main>\n                </div>\n                <Region name=\"footer\" as=\"footer\" className=\"rp-app__footer rp-app__slot\" />\n            </div>\n        </div>\n    )\n}\n",
  "css": "/* Structure only. The canvas is the theme's sidebar colour with its texture (--rp-noise, a theme\n   stylesheet variable); slots are bare and stretch their widgets. */\n/* --rp-shell-header: the one top-band height; the header widget and the sidebar's header row both\n   use it, so they line up as one band. */\n.rp-app {\n    --rp-shell-header: 3.5rem;\n    display: flex; height: 100%; width: 100%; min-height: 0; overflow: hidden;\n    background-color: var(--sidebar, var(--muted)); color: var(--foreground);\n}\n.rp-app[data-texture=\"noise\"] { background-image: var(--rp-noise, none); }\n\n.rp-app__slot { min-width: 0; display: flex; flex-direction: column; }\n.rp-app__slot > [data-rp-widget] { flex: 0 0 auto; min-width: 0; }\n.rp-app__slot:not(:has([data-rp-widget])) { display: none; }\n\n/* Sidebar: full height; its widget fills it and sets its own width. */\n.rp-app__sidebar { flex: 0 0 auto; min-height: 0; }\n.rp-app__sidebar > [data-rp-widget] { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }\n.rp-app__sidebar > [data-rp-widget] > * { flex: 1 1 auto; min-height: 0; }\n\n.rp-app__column { display: flex; flex: 1 1 auto; min-width: 0; min-height: 0; flex-direction: column; }\n.rp-app__row { display: flex; flex: 1 1 auto; min-height: 0; padding: 0 4px 4px 0; }\n\n/* The inset card: bg-background m-2 mt-0 ml-0 rounded-md border shadow-sm. */\n.rp-app__card {\n    display: flex; flex: 1 1 auto; flex-direction: column; min-width: 0; min-height: 0; overflow: hidden;\n    margin: 0 8px 8px 0; border: 1px solid var(--border); border-radius: calc(var(--radius) - 2px);\n    background: var(--background); box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);\n}\n/* No sidebar beside the card (none placed, slid off canvas, or a mobile sheet): keep a left margin. */\n.rp-app:not(:has(.rp-app__sidebar [data-rp-widget])) .rp-app__card,\n.rp-app:has([data-slot=\"sidebar\"][data-collapsible=\"offcanvas\"]) .rp-app__card { margin-left: 8px; }\n@container rp-page (max-width: 767px) { .rp-app__card { margin-left: 8px; } }\n\n.rp-app__scroll { flex: 1 1 auto; min-height: 0; overflow: auto; }\n.rp-app__content { --rp-pad: 24px; display: grid; gap: 16px; align-content: start; box-sizing: border-box; width: 100%; max-width: var(--rp-content-max, none); margin-inline: auto; padding: var(--rp-pad); }\n.rp-app[data-pad=\"none\"] .rp-app__content { --rp-pad: 0; }\n.rp-app[data-pad=\"sm\"] .rp-app__content { --rp-pad: 12px; }\n.rp-app[data-pad=\"lg\"] .rp-app__content { --rp-pad: 40px; }\n@container rp-page (max-width: 767px) { .rp-app__content { --rp-pad: 16px; } .rp-app[data-pad=\"none\"] .rp-app__content { --rp-pad: 0; } }\n",
