  "clientScript": "// Plain JSX on purpose: components can be written in JS/JSX as well as TS/TSX.\n// Owns its look: top border, padding, muted small text. Links come from the portal's `footer`\n// menu (useNavigation('footer'), menu records only): groups become labelled link clusters.\nimport { usePortal, useNavigation, Link } from '@portal/runtime'\nimport { Icon } from 'components:icon'\n\nfunction FooterLink({ item }) {\n    const cls = 'inline-flex items-center gap-1.5 rounded-sm text-xs text-muted-foreground no-underline hover:text-foreground hover:underline focus-visible:outline-2 focus-visible:outline-ring'\n    const body = (\n        <>\n            {item.icon ? <Icon name={item.icon} className=\"size-3.5\" fallback={false} /> : null}\n            <span>{item.label}</span>\n        </>\n    )\n    if (item.type === 'url') {\n        return (\n            <a {...item.attrs} href={item.href} target={item.target} rel=\"noreferrer\" title={item.tooltip} className={cls}>\n                {body}\n            </a>\n        )\n    }\n    return (\n        <Link {...item.link} title={item.tooltip} aria-current={item.active ? 'page' : undefined} className={cls + (item.active ? ' text-foreground font-medium' : '')}>\n            {body}\n        </Link>\n    )\n}\n\nexport default function SiteFooter({ options }) {\n    const { release, theme } = usePortal()\n    const nav = useNavigation(options?.menu || 'footer')\n    const items = nav.source === 'menu' ? nav.items : []\n    const loose = items.filter((i) => i.type !== 'group' && i.type !== 'separator')\n    const groups = items.filter((i) => i.type === 'group')\n    const parts = [options?.text || 'React Portal', release ? `release rev ${release.version}` : 'unprocessed', theme ? theme.name || theme.key : 'no theme']\n    return (\n        <footer className=\"flex flex-col gap-3 border-t px-6 py-3 text-xs text-muted-foreground\">\n            {loose.length || groups.length ? (\n                <nav aria-label={(nav.menu && nav.menu.name) || 'Footer'} className=\"flex flex-wrap items-start gap-x-8 gap-y-3\">\n                    {loose.length ? (\n                        <ul className=\"m-0 flex list-none flex-wrap items-center gap-x-4 gap-y-1 p-0\">\n                            {loose.map((item) => (\n                                <li key={item.id}>\n                                    <FooterLink item={item} />\n                                </li>\n                            ))}\n                        </ul>\n                    ) : null}\n                    {groups.map((group) => (\n                        <div key={group.id} className=\"flex flex-col gap-1\">\n                            <span {...group.attrs} className=\"text-[11px] font-semibold tracking-wider text-foreground/80 uppercase\">\n                                {group.label}\n                            </span>\n                            <ul className=\"m-0 flex list-none flex-col gap-1 p-0\">\n                                {group.children\n                                    .filter((c) => c.type !== 'separator' && c.type !== 'group')\n                                    .map((item) => (\n                                        <li key={item.id}>\n                                            <FooterLink item={item} />\n                                        </li>\n                                    ))}\n                            </ul>\n                        </div>\n                    ))}\n                </nav>\n            ) : null}\n            <div>{parts.join(' · ')}</div>\n        </footer>\n    )\n}\n",
