  "clientScript": "import { useState } from 'react'\r\nimport { usePortal, useNavigation, useSidebar, Link } from '@portal/runtime'\r\nimport { Button } from 'components:button'\r\nimport { SidebarTrigger } from 'components:sidebar'\r\nimport { Icon } from 'components:icon'\r\nimport { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, DropdownMenuGroup, DropdownMenuLabel, DropdownMenuSeparator } from 'components:dropdown-menu'\r\nimport { ModeToggle } from './parts/ModeToggle'\r\n\r\ntype Options = { brand?: string; menu?: string; showNav?: boolean; sidebarTrigger?: boolean }\r\n\r\n/**\r\n * Portal-level header. Owns its look: 56px bar, card background, bottom border.\r\n * The menu comes from useNavigation() (active item resolved by the host). On a narrow frame the\r\n * menu collapses into a dropdown. The click counter proves it stays mounted across navigation.\r\n */\r\nexport default function SiteHeader({ options = {} }: { options?: Options }) {\r\n    const { portal } = usePortal()\r\n    const nav = useNavigation(options.menu || 'primary')\r\n    const { isMobile } = useSidebar()\r\n    const [clicks, setClicks] = useState(0)\r\n    // Top level: links, and groups as dropdowns. The mobile menu lists every link.\r\n    const top = nav.items.filter((i: any) => i.type !== 'separator')\r\n    const links = nav.items.flatMap((i: any) => (i.type === 'group' ? i.children : [i])).filter((i: any) => i.type === 'route' || i.type === 'page' || i.type === 'url')\r\n    const showNav = options.showNav !== false\r\n\r\n    return (\r\n        <div className=\"flex h-14 shrink-0 items-center gap-4 border-b bg-card px-4 text-card-foreground sm:px-6\">\r\n            {options.sidebarTrigger !== false ? <SidebarTrigger className=\"-ml-1\" /> : null}\r\n            <Link to=\"\" className=\"truncate text-lg font-bold text-primary no-underline\">\r\n                {options.brand || portal?.name || 'Portal'}\r\n            </Link>\r\n            {showNav && !isMobile ? (\r\n                <nav aria-label=\"Main\" className=\"flex min-w-0 flex-1 items-center gap-1 overflow-x-auto\">\r\n                    {top.map((item: any) => (item.type === 'group' ? <GroupMenu key={item.id} group={item} /> : <HeaderLink key={item.id} item={item} />))}\r\n                </nav>\r\n            ) : (\r\n                <div className=\"flex-1\" />\r\n            )}\r\n            {showNav && isMobile ? <MobileMenu links={links} /> : null}\r\n            <Button variant=\"outline\" size=\"sm\" onClick={() => setClicks(clicks + 1)} title=\"Local state survives page navigation\" className=\"hidden sm:inline-flex\">\r\n                Header clicks: {clicks}\r\n            </Button>\r\n            <ModeToggle />\r\n        </div>\r\n    )\r\n}\r\n\r\nconst LINK = 'inline-flex items-center gap-1.5 rounded-md px-2 py-1 text-sm whitespace-nowrap no-underline hover:bg-muted '\r\n\r\nfunction HeaderLink({ item }: { item: any }) {\r\n    if (item.type === 'url') {\r\n        return (\r\n            <a {...item.attrs} href={item.href} target={item.target} rel=\"noreferrer\" title={item.tooltip} className={LINK + 'text-foreground hover:text-primary'}>\r\n                {item.label}\r\n            </a>\r\n        )\r\n    }\r\n    return (\r\n        <Link {...item.link} title={item.tooltip} aria-current={item.active ? 'page' : undefined} className={LINK + (item.active ? 'font-medium text-primary' : 'text-foreground hover:text-primary')}>\r\n            {item.label}\r\n        </Link>\r\n    )\r\n}\r\n\r\n/** A group: a dropdown of its links (nested groups become labelled sections). */\r\nfunction GroupMenu({ group }: { group: any }) {\r\n    const entries = (items: any[]): any[] =>\r\n        items.map((item: any) => {\r\n            if (item.type === 'separator') return <DropdownMenuSeparator key={item.id} />\r\n            if (item.type === 'group') {\r\n                return (\r\n                    <DropdownMenuGroup key={item.id}>\r\n                        <DropdownMenuLabel {...item.attrs}>{item.label}</DropdownMenuLabel>\r\n                        {entries(item.children)}\r\n                    </DropdownMenuGroup>\r\n                )\r\n            }\r\n            const el = item.type === 'url' ? <a {...item.attrs} href={item.href} target={item.target} rel=\"noreferrer\" /> : <Link {...item.link} />\r\n            return (\r\n                <DropdownMenuItem key={item.id} render={el} title={item.tooltip} className={item.active ? 'font-medium text-primary' : undefined}>\r\n                    {item.icon ? <Icon name={item.icon} className=\"mr-2 size-4\" fallback={false} /> : null}\r\n                    <span>{item.label}</span>\r\n                </DropdownMenuItem>\r\n            )\r\n        })\r\n    return (\r\n        <DropdownMenu>\r\n            <DropdownMenuTrigger\r\n                render={<button type=\"button\" {...group.attrs} className={LINK + 'cursor-pointer border-0 bg-transparent ' + (group.active ? 'font-medium text-primary' : 'text-foreground hover:text-primary')} />}\r\n            >\r\n                <span>{group.label}</span>\r\n                <Icon name=\"chevron-down\" className=\"size-3.5 opacity-70\" />\r\n            </DropdownMenuTrigger>\r\n            <DropdownMenuContent align=\"start\" className=\"min-w-48\">\r\n                <DropdownMenuGroup>{entries(group.children)}</DropdownMenuGroup>\r\n            </DropdownMenuContent>\r\n        </DropdownMenu>\r\n    )\r\n}\r\n\r\nfunction MobileMenu({ links }: { links: any[] }) {\r\n    return (\r\n        <DropdownMenu>\r\n            <DropdownMenuTrigger render={<Button variant=\"outline\" size=\"icon\" aria-label=\"Open menu\" />}>\r\n                <Icon name=\"menu\" />\r\n            </DropdownMenuTrigger>\r\n            <DropdownMenuContent align=\"end\" className=\"min-w-48\">\r\n                <DropdownMenuGroup>\r\n                    <DropdownMenuLabel>Menu</DropdownMenuLabel>\r\n                    {links.map((item) =>\r\n                        item.type === 'url' ? (\r\n                            <DropdownMenuItem key={item.id} render={<a {...item.attrs} href={item.href} target={item.target} rel=\"noreferrer\" />}>\r\n                                {item.label}\r\n                            </DropdownMenuItem>\r\n                        ) : (\r\n                            <DropdownMenuItem key={item.id} render={<Link {...item.link} />} className={item.active ? 'font-medium text-primary' : undefined}>\r\n                                {item.label}\r\n                            </DropdownMenuItem>\r\n                        )\r\n                    )}\r\n                </DropdownMenuGroup>\r\n            </DropdownMenuContent>\r\n        </DropdownMenu>\r\n    )\r\n}\r\n",
