  "clientScript": "import { Region, useBlock } from '@portal/runtime'\n\n/** Two panes (start / end) with an optional divider; stacks on mobile by default. */\nexport default function Split() {\n    const { rootProps, options } = useBlock()\n    const cls = ['rp-split', options.divider ? 'rp-split--divider' : '', rootProps.className].filter(Boolean).join(' ')\n    return (\n        <div {...rootProps} className={cls}>\n            <Region name=\"start\" className=\"rp-split__pane\" />\n            <Region name=\"end\" className=\"rp-split__pane\" />\n        </div>\n    )\n}\n",
  "css": ".rp-split {\n    display: grid;\n    grid-template-columns: var(--rp-split, minmax(0, 1fr) minmax(0, 1fr));\n    gap: var(--rp-split-gap, 1.5rem);\n    align-items: start;\n}\n\n.rp-split__pane {\n    display: flex;\n    flex-direction: column;\n    gap: var(--rp-split-gap, 1.5rem);\n    min-width: 0;\n}\n\n.rp-split--divider > .rp-split__pane + .rp-split__pane {\n    border-inline-start: 1px solid var(--border);\n    padding-inline-start: var(--rp-split-gap, 1.5rem);\n}\n",
