  "clientScript": "import { Region } from '@portal/runtime'\n\ntype Options = { header?: 'full' | 'beside-sidebar'; contentPadding?: 'none' | 'sm' | 'md' | 'lg' }\n\n/**\n * Structure only: places header / sidebar / main / footer and makes main the only scroller.\n * The widgets in each slot own their look (height, borders, background, width, collapse).\n * Options switch CSS (data attributes), never the element tree, so changing them never\n * remounts a widget.\n */\nexport default function StandardLayout({ options = {} }: { options?: Options }) {\n    const header = options.header === 'beside-sidebar' ? 'beside-sidebar' : 'full'\n    const pad = ['none', 'sm', 'md', 'lg'].includes(options.contentPadding as string) ? options.contentPadding : 'md'\n    return (\n        <div className=\"rp-std\" data-header={header} data-pad={pad}>\n            <Region name=\"header\" as=\"header\" className=\"rp-std__header rp-std__slot\" />\n            <Region name=\"sidebar\" as=\"aside\" className=\"rp-std__sidebar rp-std__slot\" />\n            <main className=\"rp-std__main\">\n                <Region name=\"main\" className=\"rp-std__content\" />\n            </main>\n            <Region name=\"footer\" as=\"footer\" className=\"rp-std__footer rp-std__slot\" />\n        </div>\n    )\n}\n",
  "css": "/* Structure only. Fills the frame the host gives it; main takes the remaining space and is the only\n   scroller. Slots are bare: no size, border, background or font of their own. Each slot stretches its\n   widgets (a sidebar widget gets the full slot height); the widgets size and style themselves. */\n.rp-std {\n    display: grid; height: 100%; width: 100%; min-height: 0; overflow: hidden;\n    background: var(--background); color: var(--foreground);\n    grid-template-columns: auto minmax(0, 1fr);\n    grid-template-rows: auto minmax(0, 1fr) auto;\n    grid-template-areas: \"header header\" \"sidebar main\" \"footer footer\";\n}\n/* Full-height sidebar: the header (and footer) only span the main column. */\n.rp-std[data-header=\"beside-sidebar\"] { grid-template-areas: \"sidebar header\" \"sidebar main\" \"sidebar footer\"; }\n\n.rp-std__slot { min-width: 0; min-height: 0; display: flex; flex-direction: column; }\n.rp-std__slot > [data-rp-widget] { flex: 0 0 auto; min-width: 0; }\n.rp-std__header { grid-area: header; }\n.rp-std__footer { grid-area: footer; }\n.rp-std__sidebar { grid-area: sidebar; }\n.rp-std__sidebar > [data-rp-widget] { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }\n.rp-std__sidebar > [data-rp-widget] > * { flex: 1 1 auto; min-height: 0; }\n.rp-std__header:not(:has([data-rp-widget])), .rp-std__sidebar:not(:has([data-rp-widget])), .rp-std__footer:not(:has([data-rp-widget])) { display: none; }\n\n.rp-std__main { grid-area: main; min-width: 0; min-height: 0; overflow: auto; }\n/* Content is centred and capped at the page's content width (--rp-content-max, set by the host from the\n   page setting / portal default; none = full bleed). */\n.rp-std__content { --rp-pad: 24px; display: grid; gap: 16px; align-content: start; padding: var(--rp-pad); min-height: 100%; box-sizing: border-box; width: 100%; max-width: var(--rp-content-max, none); margin-inline: auto; }\n.rp-std[data-pad=\"none\"] .rp-std__content { --rp-pad: 0; }\n.rp-std[data-pad=\"sm\"] .rp-std__content { --rp-pad: 12px; }\n.rp-std[data-pad=\"lg\"] .rp-std__content { --rp-pad: 40px; }\n@container rp-page (max-width: 767px) {\n    .rp-std__content { --rp-pad: 16px; }\n    .rp-std[data-pad=\"none\"] .rp-std__content { --rp-pad: 0; }\n}\n",
  "serverScript": "",
